# NEW HYPOTHESIS: For each row, detect blocks/strips of non-background cells
# and mark their corresponding regions in output

rows_in = G['Demo pair 1 input']
rows_out = G['Demo pair 1 output']

def analyze_row(row):
    """Find contiguous blocks of non-background values"""
    # Background seems to be 2 in demo
    bg = 2
    blocks = []  # [(start_idx, end_idx, value)]
    curr_block = None

    for i, val in enumerate(row):
        if val == bg:
            if curr_block:
                blocks.append((curr_block[0], curr_block[1], curr_block[2]))
                curr_block = None
        else:
            if curr_block is None:
                curr_block = (i, i, val)
            else:
                curr_block = (curr_block[0], i, curr_block[2])

    if curr_block:
        blocks.append((curr_block[0], curr_block[1], curr_block[2]))
    return blocks

print("Analyzing rows 0-4:")
for r in range(5):
    inp_blocks = analyze_row(rows_in[r])
    out_row = rows_out[r]

    print(f"\nRow {r}:")
    print(f"  Input non-bg blocks: {inp_blocks}")
    print(f"  Output row: {''.join(map(str, out_row))}")

    # Check if output 2s align with any block projection
    out_2_ranges = []
    for c in range(len(out_row)):
        if out_row[c] == 2:
            # Find start and end of consecutive 2s
            if not out_2_ranges or (out_2_ranges[-1][1] != c-1):
                start = c
                while c < len(out_row) and out_row[c] == 2:
                    c += 1
                out_2_ranges.append((start, c-1))

    print(f"  Output 2-ranges: {out_2_ranges}")

