# Let me try a completely different approach
# Maybe the task is to count/track individual "objects" and mark their occurrences?

demo_in = G['Demo pair 1 input']
h, w = len(demo_in), len(demo_in[0])
bg = 2

# For each unique non-background value, track its run-lengths
print("Tracking run-lengths of each non-bg value:")

unique_non_bg_values = set()
for r in range(h):
    for c in range(w):
        if demo_in[r][c] != bg:
            unique_non_bg_values.add(demo_in[r][c])

print(f"Unique non-bg values: {sorted(unique_non_bg_values)}")

# Look at runs of each non-bg value
for val in sorted(unique_non_bg_values):
    # Find all runs of this value
    runs = []
    current_val = None
    run_len = 0
    run_start = 0

    for r in range(h):
        for c in range(w):
            if demo_in[r][c] == val:
                if current_val != val:
                    current_val = val
                    run_len = 1
                    run_start = c
                else:
                    run_len += 1
            else:
                if current_val == val:
                    runs.append((run_start, run_start + run_len, r))
                current_val = None
                run_len = 0

    print(f"\nValue {val} runs:")
    print(f"  Found {len(runs)} runs")

